/*==========================================================================*/

/*--------------------------------------------------------------------------*/

Sense_Rs_Input_Cfg* sense_rs_pi_cfg( Sense_Rs_Input_Selector selector  )
{    
    UInt8 action = sense_rs_input_config->inputs[selector]-1 ; 
    
    if( action < SENSE_RS_IN_FUNCTION_COUNT ) return (Sense_Rs_Input_Cfg*)&sense_rs_pi_cfg_table[action];
    
    return NULL ;       
}


